B.Oz=new A.ia(1,"takbir")
B.alx=new A.bV([B.bq,"Raise hands so thumbs level with earlobes, fingertips level with upper ear.",B.bM,"Men touch earlobes with thumbs; women raise hands to shoulder height."],t.d)
